import React, { useEffect } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';

import { useDispatch, useSelector } from '@src/lib/redux';
import {
  selectHomepage,
  selectHomepageError,
  selectHomepageStatus,
} from '../selector';
import { selectLocation } from '../../HomepageSearch/selector';
import { fetchHomepage } from '../thunk';

const HomepageInfo: React.FC = () => {
  const dispatch = useDispatch();

  const homepage = useSelector(selectHomepage);
  const status = useSelector(selectHomepageStatus);
  const error = useSelector(selectHomepageError);
  const location = useSelector(selectLocation);

  useEffect(() => {
    dispatch(
      fetchHomepage({
        latitude: location?.latitude ?? 0,
        longitude: location?.longitude ?? 0,
      }),
    );
  }, [dispatch, location]);

  if (status === 'loading') {
    return <ActivityIndicator />;
  }

  if (error) {
    return <Text style={styles.error}>{error}</Text>;
  }

  if (status === 'succeeded') {
    return (
      <View style={styles.homepageInfo}>
        <Text style={styles.temperature}>{homepage?.temperature}°C</Text>
        <Text style={styles.windInfo}>
          Wind: {homepage?.windspeed} km/h, Direction: {homepage?.winddirection}°
        </Text>
      </View>
    );
  }

  return <View />;
};
export { HomepageInfo }
const styles = StyleSheet.create({
  homepageInfo: {
    backgroundColor: '#f5f5f5',
    borderRadius: 8,
    padding: 20,
    width: '100%',
    maxWidth: 350,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.5,
    elevation: 5,
  },
  temperature: {
    fontSize: 36,
    fontWeight: 'bold',
    color: '#000000',
  },
  windInfo: {
    fontSize: 16,
    color: '#555',
    marginTop: 8,
  },
  statusText: {
    fontSize: 18,
    color: '#333',
    textAlign: 'center',
    marginTop: 20,
  },
  error: {
    fontSize: 18,
    color: 'red',
    textAlign: 'center',
    marginTop: 20,
  },
});

export default styles;
