import {
  BaseButton,
  Carousel,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useTranslation } from '@core/service';
import { View } from 'react-native';
import Animated, { useAnimatedScrollHandler } from 'react-native-reanimated';
import { FlatList } from 'react-native-gesture-handler';
import { VideoBackground } from '../../components';
import { isEmpty } from 'lodash';
import { HpProductSectionBackground } from '@src/domain/entities/homepage';
type PageScrollPropsType = {
  indexHorizontal: number;
  setIndexHorizontal: (index: number) => void;
  dataVideo: HpProductSectionBackground[] | string[];
  isMuteVideo?: boolean;
  isPauseVideo?: boolean;
}
const FlatListAnimated = Animated.createAnimatedComponent(FlatList);
const PageScroll: React.FC<PageScrollPropsType> = (props) => {
  const { theme } = useTheme();
  const { t, i18n } = useTranslation(['PageScroll']);
  const { indexHorizontal, setIndexHorizontal, dataVideo, isMuteVideo, isPauseVideo } = props;
  const styles = useStyles();
  const devicesWidth = theme.Size.DEVICE_WIDTH;
  const flashListRef = useRef(null);
  const [currentIndex, setCurrentIndex] = useState(indexHorizontal);
  useEffect(() => {
    if (indexHorizontal !== currentIndex) {
      flashListRef?.current?.scrollToIndex({
        index: indexHorizontal,
      });
    }
  }, [indexHorizontal]);
  const onVideoEnd = () => {
    if (currentIndex < dataVideo?.length - 1) {
      setIndexHorizontal(currentIndex + 1);
    } else {
      setIndexHorizontal(0)
    }
  };
  const renderItems = ({ item, index }) => {
    return (
      <VideoBackground
        muted={isMuteVideo}
        pause={isPauseVideo || indexHorizontal !== index}
        repeat={true}
        onVideoEnd={onVideoEnd}
        source={!isEmpty(item?.attributes?.media_item) ? item?.attributes?.media_item : !isEmpty(item?.attributes?.media_items)? item?.attributes?.media_items: item?.attributes?.background_media}
      />
    );
  }


  const scrollHandler = (event) => {
    const totalWidth = event.nativeEvent.layoutMeasurement.width;
    const xPosition = event.nativeEvent.contentOffset.x;
    const newIndex = Math.round(xPosition / totalWidth);
    if (newIndex !== currentIndex) {
      if (newIndex > 0) {
        setCurrentIndex(newIndex);
        newIndex != indexHorizontal && setIndexHorizontal(newIndex);
      } else {
        setCurrentIndex(0);
        newIndex != indexHorizontal && setIndexHorizontal(0);
      }
    }
  };
  return (
    <View style={styles.container}>
      <FlatListAnimated
        // onIndexChange={function (index: number): void { }}
        // estimatedItemSize={devicesWidth}
        ref={flashListRef}
        onScroll={scrollHandler}
        data={dataVideo}
        style={{ flex: 1 }}
        horizontal
        keyExtractor={(item, index) => index?.toString()}
        showsHorizontalScrollIndicator={false}
        snapToAlignment={'start'}
        snapToInterval={devicesWidth} // Adjust to your content width
        decelerationRate={'fast'}
        renderItem={renderItems}
        nestedScrollEnabled={true}
        extraData={[currentIndex, indexHorizontal, isPauseVideo]}
        bounces={false}
      />
      {/* <VideoBackground /> */}
    </View>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    flex: 1,
    backgroundColor: 'transparent',
  },
}));
export { PageScroll };
