import { IHomepageRepository } from '@src/domain/interfaces/homepage';
import { Homepage } from '../../../domain/entities/homepage';
import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { GetHomepageQuery } from '@src/application/homepage/queries/get_homepage_query';
import { HttpService } from '@core/service';
import { HOMEPAGE_BASE_URL } from '@src/config';

@injectable()
export class HomepageRepository
  extends HttpService
  implements IHomepageRepository {
  constructor() {
    super({ baseURL: HOMEPAGE_BASE_URL });
  }

  async getHomepage<TParameter>(query: Query<TParameter>): Promise<Homepage> {
    const request = query.query as unknown as GetHomepageQuery;
    const url = '/v1/forecast';
    const params = {
      latitude: String(request.latitude),
      longitude: String(request.longitude),
      current_homepage: 'true',
    };

    const response = await this.get<{ current_homepage: any }>(url, {
      params: params,
    });

    return this.parseHomepage(response.data?.current_homepage);
  }

  private parseHomepage(data: any): Homepage {
    return {
      temperature: Number(data.temperature),
      windspeed: Number(data.windspeed),
      winddirection: Number(data.winddirection),
      homepagecode: Number(data.homepagecode),
      time: String(data.time),
    };
  }
}
