import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback, useEffect } from 'react';
import { eventBusService, Storage, UserService, useTranslation } from '@core/service';
import { Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { HomePageMenuItem, HomePageMenuItemType } from './HomePageMenuItem';
import { CTAButtonWelcome, CTAButtonWelcomeHome } from '../CTAButtonWelcome';
import { CTAButtonWelcomeLogin } from '../CTAButtonWelcome/CTAButtonWelcomeLogin';
import { isEmpty } from 'lodash';
import { HomePageMenu as HomePageMenuType, HpWelcome, HpWelcomeBackground, MenuItem } from '@src/domain/entities/homepage';

const homePageData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepagemenu.json');
const homePageWelcomeBackground = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageWelcomeBackground.json');

type HomePageMenuPropsType = {
  data: HpWelcomeBackground;
  homeMenu: HomePageMenuType;
};
const HomePageMenu: React.FC<HomePageMenuPropsType> = (props) => {
  const { theme } = useTheme();
  const { data, homeMenu } = props;
  const { t, i18n } = useTranslation(['HomePageMenu']);
  const styles = useStyles();
  const [isPersional, setIsPersional] = useState(true);

  const insets = useSafeAreaInsets();
  const [videoIndex, setVideoIndex] = useState(0);
  const [isLogin, setIsLogin] = useState(false);

  useEffect(() => {
    const listenLogin = eventBusService.on(
      'auth.login_success',
      () => {
        setIsLogin(true)
      },
    );
    const listenLogout = eventBusService.on(
      'auth.logout_success',
      () => {
        setIsLogin(false)
      },
    );

    return () => {
      listenLogin.remove();
      listenLogout.remove();
    };
  }, []);
  useEffect(() => {
    UserService.getUser().then((user) => {
      console.log('UserData', user);
      const isCorp = (user?.CORP?.length ?? 0) > 0;
      const isIndi = !!user?.INDI;
      const corpSegment = isCorp ? 'CORP' : null;
      const indiSegment = isIndi ? 'INDI' : null;
      const segment = corpSegment ?? indiSegment ?? '';
      if (!isEmpty(user)) {
        setIsLogin(true)
      }
    });
  }, []);
  return (
    <View style={[styles.container]}>
      <CTAButtonWelcomeHome data={data?.attributes?.cta_button}/>
      <ScrollView horizontal contentContainerStyle={styles.contentContainerStyle}>
        {homeMenu?.attributes?.menu_items?.map((item: MenuItem, index: number) => {
          return (
            <HomePageMenuItem item={item} index={index} key={item.id} />
          );
        })}
      </ScrollView>

    </View>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    paddingHorizontal: theme.Size.Horizontal.Medium,
    gap: theme.Size.Vertical.Base,
  },
  contentContainerStyle: {
    justifyContent: 'space-between',
    gap: 12,
  },
}));
export { HomePageMenu };
