import React from 'react';
import { Image, Text } from 'react-native';
import type { RadioButtonProps } from './ChoiceProps';
import { BaseButton, createStyles } from '@core/ui';
import { icRadioCheck, icRadioUncheck } from '@src/assets';

const RadioButton: React.FC<RadioButtonProps> = ({
  checked,
  text,
  onPress,
  textStyle,
  containerStyle,
  isDisable = false,
  position = 'left',
  componentRight,
  componentLeft,
}) => {
  const styles = useStyles();

  const _buildRadio = () => {
    if (checked) {
      return <Image source={icRadioCheck} style={styles.iconStyle} />;
    }
    return <Image source={icRadioUncheck} style={styles.iconStyle} />;
  };

  return (
    <BaseButton
      disabled={isDisable}
      onPress={onPress}
      style={[styles.container, containerStyle]}
    >
      {position === 'left' && _buildRadio()}
      {componentLeft && componentLeft}
      {text && <Text style={[styles.small, textStyle]}>{text}</Text>}
      {componentRight && componentRight}
      {position === 'right' && _buildRadio()}
    </BaseButton>
  );
};

export { RadioButton };

const useStyles = createStyles((theme) => ({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  disable: {
    opacity: 0.5,
  },
  small: {
    ...theme.Typography.TextCaption100.Regular,
    paddingLeft: theme.Size.Horizontal.Base,
  },
  iconStyle: {
    width: theme.Scaling.ms(24),
    height: theme.Scaling.ms(24),
  },
  large: {
    ...theme.Typography.TextSubheadline.Regular,
    paddingLeft: theme.Size.Horizontal.Base,
  },
}));
