import { BaseButton, createStyles, Text, useTheme } from '@core/ui';
import { BannerWelcome } from '@src/presentation/homepage/components';
import { HomePageMenu } from '@src/presentation/homepage/components/HomePageMenu';
import { Hotline } from '@src/presentation/homepage/components/Hotline';
import { LeftMenu } from '@src/presentation/homepage/components/LeftMenu';
import { Pagination } from '@src/presentation/homepage/components/Pagination/Pagination';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
// import { useTranslation } from '@core/service';
import { StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { PageScroll } from './PageScroll';
import { HpWelcome } from '@src/domain/entities/homepage';

type PageWelcomePropsType = {
  data: HpWelcome;
  isMuteVideo: boolean;
  setMuteVideo: () => void;
  isPauseVideo?: boolean;
};

const PageWelcome: React.FC<PageWelcomePropsType> = (props) => {
  const { theme } = useTheme();
  // const { t, i18n } = useTranslation(['PageWelcome']);
  const { data, setMuteVideo, isMuteVideo, isPauseVideo } = props;

  const insets = useSafeAreaInsets();
  const styles = useStyles();
  const [currentPage, setCurrentPage] = useState(0);
  const [muted, setIsMuteVideo] = useState(isMuteVideo);
  const handlePagination = (page) => {
    setCurrentPage(page);
  };
  const handleMuteVideo = useCallback(() => {
    setMuteVideo(!muted);
    setIsMuteVideo(!muted);
  }, [muted]);
  const dataBackground = data?.attributes?.hp_news_banners?.data?.[0]?.attributes?.hd_customer_type?.data?.attributes?.hp_welcome_backgrounds?.data
  return (
    <View style={{ ...StyleSheet.absoluteFillObject, backgroundColor: 'transparent' }}>
      <PageScroll
        dataVideo={dataBackground}
        isMuteVideo={isMuteVideo}
        indexHorizontal={currentPage}
        isPauseVideo={isPauseVideo}
        setIndexHorizontal={setCurrentPage}
      />
      <>
        <BannerWelcome dataBanner={data?.attributes?.hp_news_banners?.data?.[0]?.attributes?.title} />
        <View
          style={[styles.page, { bottom: theme.Size.ms(56) + 76 + insets.bottom }]}
        >
          <LeftMenu
            setMuteVideo={handleMuteVideo}
            isMuteVideo={muted}
            data={dataBackground?.[currentPage]?.attributes?.hp_left_menus?.data}
          />
          <Pagination
            currentPage={currentPage}
            setCurrentPage={handlePagination}
            totalPages={dataBackground?.length}
          />
          <HomePageMenu data={dataBackground?.[currentPage]}  homeMenu={data?.attributes?.hp_home_menu?.data} />
        </View>
      </>
    </View>

  );
};
const useStyles = createStyles((theme) => ({
  page: {
    position: 'absolute',
    gap: theme.Size.Vertical.Medium,
    justifyContent: 'flex-end',
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'transparent',
  },
}));
export { PageWelcome };
