import { TYPES } from '@src/di/types/types';
import type { IHomepageRepository } from '@src/domain/interfaces/homepage';
import { Query } from '@src/domain/models/query';
import { inject } from 'inversify';
import { GetHomepageQuery } from './get_homepage_query';

export class GetHomepageHandler {
  private readonly _homepageRepository: IHomepageRepository;

  constructor(
    @inject(TYPES.IHomepageRepository) homepageRepository: IHomepageRepository,
  ) {
    this._homepageRepository = homepageRepository;
  }

  handle(query: Query<GetHomepageQuery>) {
    return this._homepageRepository.getHomepage(query);
  }
}
