import { BaseButton, createStyles, Text, useTheme } from '@core/ui';
import React, { useEffect, useRef, useState } from 'react';
import { useTranslation } from '@core/service';
import { Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { HomePageMenu } from '../HomePageMenu';
import Video, { SelectedTrackType, VideoRef } from 'react-native-video';
import { LeftMenu } from '../LeftMenu';
import { Hotline } from '../Hotline';
import { imgVideoBlur } from '@src/assets';

type VideoBackgroundPropsType = {
  pause: boolean;
  onVideoEnd: () => void;
  source: mediaType;
  repeat?: boolean;
  muted?: boolean;
};
type mediaType = {
  id: number;
  name: string;
  media: string;
  destination: string;
};
const VideoBackground: React.FC<VideoBackgroundPropsType> = (props) => {
  const { theme } = useTheme();
  const { t, i18n } = useTranslation(['VideoBackground']);
  const { pause, onVideoEnd, source, repeat = false, muted = false } = props;
  const insets = useSafeAreaInsets();
  const [isMuteVideo, setIsMuteVideo] = useState(muted);
  const videoRef = useRef<VideoRef>(null);
  const styles = useStyles();
  useEffect(() => {
    if (isMuteVideo != muted) {
      setIsMuteVideo(muted);
    }
  }, [isMuteVideo, muted]);

  return (
    <Video
      // Can be a URL or a local file.
      source={{
        uri: source?.media
          ? source?.media
          : 'https://d24fd5v098kxjg.cloudfront.net/Home_72847050d1.mp4',
      }}
      // Store reference
      ref={videoRef}
      onEnd={onVideoEnd}
      paused={pause}
      repeat={repeat}
      resizeMode="cover"
      ignoreSilentSwitch={'ignore'}
      removeClippedSubviews={true}
      muted={isMuteVideo}
      selectedAudioTrack={{ type: SelectedTrackType.SYSTEM }}
      style={styles.video}
      onError={(e) => console.log('videoError', e)}
      poster={{
        source: imgVideoBlur,
        style: {
          width: theme.Size.DEVICE_WIDTH,
          height: theme.Size.DEVICE_HEIGHT,
        },
        // ...
      }}
    />
  );
};
const useStyles = createStyles((theme) => ({
  container: {
    flex: 1,
    backgroundColor: 'red',
    // paddingHorizontal: theme.Size.Horizontal.Medium,
  },
  video: {
    width: theme.Size.DEVICE_WIDTH,
    height: theme.Size.DEVICE_HEIGHT,
  },
}));
export { VideoBackground };
