import { RouteProp, useNavigation, useRoute } from '@react-navigation/native';
import React, { FC, useEffect, useState } from 'react';
import { useTranslation } from '@core/service';
import { LoadingBlockerView, createStyles } from '@core/ui';
import { Image, ImageBackground, TouchableOpacity, View } from 'react-native';
import { WebView } from 'react-native-webview';
import { MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import { Header } from '../components';
import { backgroundWebview, icHotlineLine } from '@src/assets';

const WebViewScreen: FC = (props) => {
  const route = useRoute<RouteProp<MainStackParamList, 'WebViewScreen'>>();
  const url = route.params?.url || '';
  const title = route.params?.title || '';
  const styles = useStyles();

  const { t } = useTranslation(['webViewScreen']);

  const [loading, setLoading] = useState(true);
  const [webKey, setWebKey] = useState(0);

  useEffect(() => {
    setWebKey((prevKey) => prevKey + 1);
  }, [url]);

  return (
    <ImageBackground
      style={styles.container}
      resizeMode="stretch"
      source={backgroundWebview}
    >
      <Header
        text={title}
        style={styles.heaederStyle}
        rightIcon={
          <TouchableOpacity>
            <Image source={icHotlineLine} style={styles.imageStyle} />
          </TouchableOpacity>
        }
      />
      <View style={styles.webviewContainer}>
        {loading && (
          <View style={styles.loadingContainer}>
            <LoadingBlockerView />
          </View>
        )}
        <WebView
          key={webKey}
          source={{ uri: url }}
          style={styles.webview}
          onLoadStart={() => setLoading(true)}
          onLoadEnd={() => setLoading(false)}
        />
      </View>
    </ImageBackground>
  );
};

const useStyles = createStyles((theme) => ({
  container: {
    flex: 1,
  },

  heaederStyle: {
    backgroundColor: 'transparent',
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%',
    backgroundColor: 'white',
    borderTopLeftRadius: theme.Size.ms(16),
    borderTopRightRadius: theme.Size.ms(16),
  },
  imageStyle: {
    width: theme.Size.ms(40),
    height: theme.Size.ms(40),
  },
  webviewContainer: {
    flex: 1,
    overflow: 'hidden', // Quan trọng để giới hạn nội dung bên trong
    borderTopLeftRadius: theme.Size.ms(16),
    borderTopRightRadius: theme.Size.ms(16),
  },
  webview: {
    flex: 1,
    backgroundColor: 'white',
  },
}));

export { WebViewScreen };
