import {
  StyleProp,
  StyleSheet,
  Text,
  TextStyle,
  TouchableOpacity,
  View,
} from 'react-native';
import React from 'react';
import { createStyles, GradientContainer, useTheme } from '@core/ui';

type BottomBarItemProps = {
  label?: string;
  icon: React.ReactNode;
  activeIcon?: React.ReactNode;
  isActive?: boolean;
  onPress: () => void;
  isFloating?: boolean;
  isFocus?: boolean;
};

const BottomBarItem = ({
  label,
  icon,
  activeIcon,
  isActive,
  onPress,
  isFloating,
  isFocus,
}: BottomBarItemProps) => {
  const { theme } = useTheme();
  const { Fonts, Size, Colors } = theme;
  const styles = useStyles()
  const TextCaption300 = {
    Bold: {
      fontFamily: Fonts.Bold,
      fontSize: Size.ms(10),
      lineHeight: Size.ms(12),
      color: Colors.Text.Black,
    },
  };
  const labelStyle: StyleProp<TextStyle> = {
    // ...theme.Typography.TextCaption300,
    ...TextCaption300.Bold,
  };

  return (
    isFocus ? <GradientContainer colorList={
      [
        { color: theme.Colors.Background.White, offset: '0%', opacity: '0.6' },
        { color: theme.Colors.Background.White, offset: '100%', opacity: '0' },
      ]
    }>
      <TouchableOpacity key={label} onPress={onPress} style={[styles.container, isFloating && { marginTop: -18, gap: 4 }]}>
        {icon}
        {label ? <Text style={labelStyle}>{label}</Text> : null}
      </TouchableOpacity>
      <View style={styles.lineActive} />
    </GradientContainer> :
      <TouchableOpacity key={label} onPress={onPress} style={[styles.container, isFloating && { marginTop: -18, gap: 4 }]}>
        {icon}
        {isFloating ? <View style={styles.labelView}>
          {label ? <Text style={[labelStyle, { color: theme.Colors.Base.White }]}>{label}</Text> : null}
        </View> : label ? <Text style={labelStyle}>{label}</Text> : null}
      </TouchableOpacity>
  );
};


export { BottomBarItem };

const useStyles = createStyles((theme) => ({
  container: {
    alignItems: 'center',
    backgroundColor: 'transparent',
    gap: 2,
    flex: 1,
    paddingTop: 10
  },
  activeIcon: {
    tintColor: 'white',
  },
  lineActive: {
    height: 2,
    width: '100%',
    backgroundColor: theme.Colors.Background.White,
    position: 'absolute',
    top: 0,
    borderBottomLeftRadius: theme.BorderRadius.xs,
    borderBottomRightRadius: theme.BorderRadius.xs,
  },
  labelView: {
    paddingHorizontal: theme.Size.ms(8),
    padVertical: theme.Size.ms(2),
    backgroundColor: "#DA2128",
    borderRadius: theme.BorderRadius.xs,

  }
}));
