import React, { useEffect } from 'react';
import { type NativeStackNavigationProp } from '@react-navigation/native-stack';
import { HomePageScreen } from '@src/presentation/homepage/screens';
import {
  BottomTabBarProps,
  createBottomTabNavigator,
} from '@react-navigation/bottom-tabs';
import { BottomBar } from '@src/presentation/homepage/components';
import { BlurView } from '@react-native-community/blur';
import { StyleSheet } from 'react-native';

export type MainScreenStackParams = {
  HomePage: any;
} & any;

export type MainScreenNavigationProp =
  NativeStackNavigationProp<MainScreenStackParams>;

const Tab = createBottomTabNavigator<MainScreenStackParams>();

const TabNavigation = ({ route }) => {
  const scrollVeticalIndex = route?.params?.scrollVeticalIndex;

  const renderTabBar = (props: BottomTabBarProps) => {
    return <BottomBar {...props} />;
  };

  return (
    <Tab.Navigator
      tabBar={renderTabBar}
      screenOptions={{
        headerShown: false,
        tabBarBackground: () => (
          <BlurView
            blurType="light"
            blurAmount={10}
            style={StyleSheet.absoluteFill}
          />
        ),
      }}
    >
      <Tab.Screen
        name="HomePage"
        component={HomePageScreen}
        initialParams={{ scrollVeticalIndex }}
      />
    </Tab.Navigator>
  );
};

export default TabNavigation;
